FIELDS={}
for line in ROWS.splitlines():
    code,*values=line.split("|")
    if len(values)!=len(KEYS) or not all(values):
        raise ValueError("Incomplete car-form translation: "+code)
    FIELDS[code]=dict(zip(KEYS,values))
FIELDS.update(EXTRA_FIELDS)

def field(key: str) -> str:
    code=locale()
    if code not in FIELDS or key not in FIELDS[code]:
        raise KeyError(f"Missing field translation: {code}/{key}")
    return FIELDS[code][key]
